INSERT INTO tmp_segfac_2024 (n, facultad, s1, s2, descripcion) VALUES
(15, 'Arquitectura', 0.00, 3.00, '"\nArquitectura (1)\n1. X Semana Técnica\nTécnica profesional en construcción de proyectos arquitectónicos (1)\n1. II Encuentro de la Construcción\nMaestría en Patrimonio arquitectónico Urbano y Paisajístico (1)\n1. II Seminario de Patrimonio"'),
(15, 'Bellas Artes', 1.00, 6.00, '"\n\n\nDanza (4)\n1. Día internacional de la Danza\n2. Periscopio Caribe: Conversatorio Marama, La magia de RAPA NUI\n3. Gala Artistica en la UA: XXXVIII Festival Folclorico Internacional de Barranquilla\n4. V Festival de la Danza\nMúsica (2)\n1. XVII Seminario Internacional de Música Yamaha\n2. XI Encuentro Internacional de Trompeta, Trombon y Bombardino\nLicenciatura en Música (1)\n1. 1er Simposio Internacional de Investigación y Educación Musical\n\n"'),
(15, 'Ciencias Básicas', 4.00, 7.00, '"(Impacto facultad) 37th International Geological Congress (IGC2024)\nFísica (6)\n1. Coloquio de física: Taller de Fundamentos de Intrumentación para Espectroscopia Optica\n2. Iron Oxide: Linking Geology, Medicine, Energy and Biotechnology\n3. Quantum Impurity Solver Based on the HIA\n4. Seminario al coloquio de Física \n5. Coloquio: Decaimiento invisible de neutrinos en oscilaciones de neutrinos en NOVA\n6. XXV Latin American Symposium On solid state physics\nQuímica (1)\n1. Cannabis medicinal: métodos y técnicas analíticas alternativas para determinar CBD/THC e investigación de nuevas aplicaciones\nMatemáticas (2)\n1. 7mo Encuentro Internacional de Investigación en Educación Matematica\n2. Encuentro Internacional de Matemáticas EIMAT 2024\nBiología (1)\n1. Educación ambiental transformadora, conservación de los ecosistemas Marino Costeros de mesoamérica"'),
(15, 'Ciencias Económicas', 7.00, NULL, '"Administración de Empresas (2)\n1. Aspectos legales de la inversión para el emprendimiento en Colombia\n2. Estudios de casos y experiencias y herramientas para consolidar modelos de negocios exitosos\nAdministración de Empresas Turísticas (7)\n1. Turismo & Paz\n2. FUTUR 2024\n3. Semana Colombo China\n4. Foro y taller de negocios verdes: Apropiación del territorio desde el ecoturismo y diseño centrado en la vida\n5. I Seminario Internacional de Desarrollo Sostenible del Turismo deportivo en los Bordes Costeros\n6. VII Encuentro de Investigadores de la Red RITMMA: Transformación Empresarial Sostenible e Inclusiva\n7. VII Simposio de turismo y globalizacion: Desarrollo de destinos sostenibles e inteligente\nEconomía (4)\n1. Incidencia del cambio climático y modelos de desarrollo\n2. X Coloquio Red de Investigación sobre fluctuaciones ciclicas y crecimiento economico\n3. Historias de desarrollo económico: Convergencia, estancamiento y rezago del ingreso per cápita en un mundo interconectado\n4. Seminario Permanente de los ODS: Avances en colombia del objetivo desarrollo sostenible 4 y las reformas pedagógicas pendientes en la universidad\nContaduría (1)\n1. 4to ENCUENTRO DE PROSPECTIVA DEL CONTADOR PÚBLICO A NIVEL NACIONAL E INTERNACIONAL"'),
(15, 'Ciencias Humanas', 8.00, 19.00, '"Filosofía (17)\n1. Filosofia en red: Hacia una topologia de la maquina de la carne. El análisis Weiliano de la tecnica\n2. IV Ciclo de Filosofía Científica \n3. Filosofia en red: Pensar en America en movimiento\n4. Filosofia en red: La racionalidad económica en el económico de jenofont\n5. Simposio Internacional filosofia y violencia\n6. Seminario internacional Filosofas y Literatas: Agnes Taubert\n7. Seminario internacional Filosofas y Literatas: Susann Sontag\n8.Seminario internacional Filosofas y Literatas: Virginia Woolf\n9. Seminario internacional Filosofas y Literatas: Simone de Beauvior\n10. Seminario internacional Filosofas y Literatas: Soledad Acosta Samper\n11. Seminario internacional Filosofas y Literatas: Audre Lorde\n12. Seminario: Intoducción al Idealismo Aleman\n13. IV Ciclo de Filosofía Científica : Filosofía de la Inteligencia Artificial \n14. Coloquio Internacionale de Filosofīa Existencial\n15. Suicidio: Voces desde la filosofía\n16. Filosofía en red: Vertigo a la existencia\n17. Filosofía en red: Vertigo a la existencia\nHistoría (8)\n1. Jornada de Estudios Historiográficos\n2. I SImposio Museos, Memorias y Procesos de Paz\n3. XVII Foro de Historia\n4. Simposio: A 100 Años del Natalicio de E.P. Thompson: Trayectorias de la historia social desde el caribe colombiano\n5. Metodología para la Planeación Territorial: Comparando las Dinámicas Territoriales de México y Colombia\n6. Métodos y Técnicas de Análisis Regional\n7. El plan de Ordenamiento territorial como generador de desarrollo: El centro histórico de Barranquilla y el área de influencia.\n8. Acueducto y el alcantarillado de Barranquilla evolución\nSociología (2)\n1. Teatrón de emociones y malestares\n2. VI Encuentro de Egresados de Sociología "'),
(15, 'Ciencias Jurídicas', 3.00, 5.00, '"Derecho (8)\n1. Crisis del Estado de Derecho\n2. XIX Congreso Nacional de Filosifa del derecho y Filosofia Social\n3. Congreso Internacional, El derecho digital en un escenario Jurídico cambiante\n4. Congreso Internacional de Derecho Procesa 2024: Innovación y desafíos en la era digital\n5. Diplomacia Cultural en Colombia y Chile, una mirada desde las RR.II\n6. XI Olimpijuris\n7. II Jornadas Colombianas de Derecho Privado\n8. II congreso regional: Juridicción de lo contencioso administrativo del caribe colombiano"'),
(15, 'Educación', 5.00, 10.00, '"Impacto a la facultad (1) Relación entre la sociedad del conocimiento, metodología de la investigación científica y producción científica estudiantil \nDoctorado de Ciencias de la Educación(1)\n1. Encuentro del Comité Curricular y de Autoevaluación Nacional del Doctorado en Ciencias de la Educación.\nLicenciatura en Lenguas Extranjeras (5)\n1. Francophonie\n2. Using children''s Literature with disability representation to foster inclusivity\n3.Entrevista sobre la cultura francofona\n4. Entrevista sobre la cultura Francofona\n5. Voces del mundo III: Encuentro de Egresados de la licenciatura de lenguas extranjeras con énfasis en inglés y frances.\nLicenciatura en Ciencias Sociales (1)\n1. Semana de la Licenciatura de Ciencias Sociales\nLicenciatura en Educación Especial (3)\n1. Educación, lenguaje e interculturalidad\n2. IV Foro nacional de Lengua de Señas en la educación Superior\n3. Convención internacional de educación Inclusiva: COnstruyendo inclusión a través del lenguaje\nLicenciatura en Humanidades y Lengua Castellana (1)\n1. Semana de las Lenguas\nMaestría en Neuropedagogía (1)\n1. V Congreso Internacional de Neuropedagogía, Lenguajes Artisticos e Inclusión\nLicenciatura en Educación Física (2)\n1. Intercambio Académico: Conferencia los retos en la Educación física, una visión desde la diversidad\n2. V Congreso Internacional de Educación Física, Recreación y Deportes.'),
(15, 'Ingeniería', 6.00, 4.00, '"Impacto a la facultad (2) \n1. Ingenieros UA por el mundo: Haciendo la diferencia \n2. Dia de la Mujer en la Ingeniería\nIngeniería en Agronegocios (1)\n1. Colombia en la Transición Energética: Oportunidades y Desafios\nIngeniería Agroindustrial (2)\n1. VII Agroingenio\n2. inteligencia Artificial aplicada a los agronegocios\nIngeniería Química (3)\n1. De Mayagüez a la estación Espacia con Egresados UA\n2. Horizonte de la Ingeniería: Innovación y Liderazgo\n3. Materiales para la sostenibilidad: IV Jornada de Ingeniería Química \nIngeniería Industrial (3)\n1. Semana de la Innovación y del Emprendimiento\n2. I Cátedra Ternium"'),
(15, 'Ciencias de la Salud', 4.00, 1.00, '1. Se realizó en marzo 04 de 2024 la conferencia en desarrollo de alimentos sustentables y saludables a partir de excedentes agroalimentarios, el cual contó con la asistencia de la Doctora Ximena Rodriguez- directora del programa de Nutrición, Universidad Bernardo O¨higgins de Chile.\n\n2. Se realizó el 9 de mayo el seminario para Socializar los resultados de la EFSA- análisis de la situación alimentaria de la población colombiana: Espedito Nastro- jefe de investigación, evaluación y seguimiento del Programa Mundial de Alimentos.WFP\n\n3. Webinar Desafíos y oportunidades de los servicios de alimentación-Calidad y Productividad - Webinar Internacional. Conferencia: Puntos críticos de la calidad e inocuidad en los Servicios de Alimentación – Yadira Rodríguez. MSc. Ciencia y Tecnología de Alimentos. Texas. E.E.U.U.\n\n4. El 7 de junio se realizó un Webinar Tendencias y Retos de la Seguridad Alimentaria y Nutricional para 2024. Retos de la SAN en los usuarios de los Bancos de alimentos. Una mirada a Chile. la Doctora Ximena Rodriguez- directora del programa de Nutrición, Universidad Bernardo O¨higgins de Chile.\n\n5. El 9 de agosto se realizó el Seminario internacional “Dietas saludables y medio ambiente en pro del Derecho humano a la alimentación adecuada”. ponencia 1 "Integración de la Medicina y Nutrición: Un Enfoque Holístico para el Bienestar Humano". DRA. SUELLEN VIEIRA ARAUJO Brasil. Ponencia 2. PONENCIA 5 (VIRTUAL): Seguridad Hídrica y su Relación con la Seguridad Alimentaria y Nutricional. DR. HUGO MELGAR QUIÑONEZ. Canada.'),
(15, 'Química y Farmacia', 3.00, NULL, '"Farmacia (3)\n1. Foro: Servicio Social Obligatorio para Quimicos Farmaceuticos\n2. Webinar Internacional “SABERES Y EXPERIENCIAS EN EL SECTOR FARMACEUTICO, UNA MIRADA INTERNACIONAL”\n3. II ENCUENTRO DE ESTUDIANTES DE QUIMICA Y FARMACIA UA-USB- UNA VISIÓN INTERNACIONAL."'),
(18, 'Arquitectura', NULL, 3.00, 'Presentaron experiencias eduativas mediadas por las TIC, los profesores Jorge Torres, Liz Romero Sanjuan y Christian Castro, siendo estos dos ultimos mereedores de premios por su innovación'),
(18, 'Bellas Artes', 4.00, 5.00, '1. ProMúsica: Ha sistematizado y optimizado el Examen de Admisión a\ntravés de una aplicación que ayuda a optimizar el proceso (prof. Ricardo Ospina) -2024-1.\n2. LiMúsica: Diseño de OVAs para las asignaturas de Historia de la Música III - (Prof. Angela Marín) - 2024-1\n3. Limúsica: Investigación Musical I (Prof. Angela Marín) - 2024-1\n4. Danza: Composición Coreográfica 1. (Yanny Manotas) - 2024-1 https://drive.google.com/drive/folders/1bSLSkFgt22wPQOkBlqGmQoBBVEnetKij\n5. Danza: Clase espejo realizada junto a la Universidad de las Artes en Guayaquil, Ecuador, se realizó de manera sincrónica y se contó con un aula inteligente del Bloque D (UA sede norte) para la realización de la misma. Constituyó un reto siendo que la naturaleza de la clase es utilizar el espacio, trasladando los cuerpos en el mismo, entrar en diálogo con lxs compañerxs y activar la escucha. Con la cámara en el enfoque adecuado y los micrófonos ajustados, se llevó a cabo esta clase espejo en una sala Zoom (Prof. Maria Lucia Acosta - 2024-2)\n6. Música: Uso de RIED, y Chords, dos apps desarrolladas por el titular de la materia (pro. Ricardo Ospina - 2024-2)\n7. Arte Dramático: Se utilizó tecnología de Realidad Virtual, por medio de HMD, tipo Oculus para visitar diferentes teatros y así contextualizar de una manera visual la historia del espacio escénico(Prof. Jorge Suarez)- 2024-2\n8. Limúsica: Composición de canción con IA SUNO (Prof. Vanessa Fontalvo) - 2024-2\n9. Limúsica: Creación de OVAs Herencias musicales - https://view.genially.com/65cce93680f7240015daeae1/interactive-image-herencias-musicales, Crucigrama Medioevo - realizado con la herramienta H5P, OVA Nacionalismo y Video-lección "DUA & Clase de Música". Los estudiantes realizaron materiales de clase con accesibilidad a partir del uso de la IA; entre estos, videos subtitulados o con audio descriptivo; también, documentos word con audio enriquecido (2024-2)'),
(18, 'Ciencias Básicas', 2.00, 1.00, '2024-1\n*Rodian Fonseca (Programa de Biología) - Analisis de datos biologicos con R, utiliza paquetes para visualización, analisis y gestión de datos.ESTA NO\n*Francisco Racedo Niebles - (Programa de Física) Creación pagina Web de prácticas de laboratorio. ESTA SI\n\n2024-2\n*Julio Romero (Programa de Matemáticas) - Curso Magistral Calculo II ESTA NO \nFALTA: Psicodrama Pedagógico matemático: un acercamiento a herramientas y técnicas grupales en la virtualidad María Serje Arias/vATEMÁTICAS'),
(18, 'Ciencias Económicas', NULL, 1.00, 'Herramientas tecnológicas para la enseñanza de investigación formativa. Caso Padlet en Administración de Empresas. Profesora Yanin Rincón Quintero'),
(18, 'Ciencias Humanas', 0.00, 1.00, 'el docente Jaime Alvarez se encuentra implementando USO DEL SICVI-567 EN EL DESARROLLO DEL SIMPOSIO DE ESTUDIOS COMPARATIVOS SOBRE BIOGRAFIAS DE CIENTIFICOS'),
(18, 'Ciencias Jurídicas', 1.00, 1.00, 'Realización de IUSCAST el podcast de los juridicos que se encuentra en la plataforma de radio digital La Publica 8NO SE REPORTÓ. EL PROFESOR RENUNCIÓ A LA UNIVERSIDAD NO SE HA CONTINUADO EL PROYECTO) experiencia indetificada por el DEV:You tube plataforma Integral Educativa: Comunicación, Investigación y Resolución de Conflictos en la clase de investigación formativa en el programa de Ciencias políticas. profesora Beatriz Bolaño García'),
(18, 'Educación', NULL, 4.00, 'El evento es realizado en el segundo semestre del año. Para el semestre 2024-2 Se realizaron 4 Practicas en innovación pedagogica: 1. Metodologías y enfoques pedagógicos innovadores mediados por las TIC: aprendizaje basado en proyectos, el aula invertida o el aprendizaje colaborativo, gamificación; Aixa Franco Buelvas, Licenciatura en Educación Especial. 2. Producción de fotografías como apropiación social del conocimiento en el marco de un proceso de investigación; Juan Pinto Siabatto, Licenciatura en Educación Artística. 3. Inclusión a través de la inteligencia artificial para personas con discapacidad visual; Martín De la Hoz Vásquez, Licenciatura en Educación Especial. 4. Redefiniendo el Aprendizaje: tableros digitales como Herramientas Colaborativas transformadoras en la clase de francés; Numas Gil Olivera, Lic. en Lenguas Extranjeras con Énfasis en inglés y francés.'),
(18, 'Ingeniería', 0.00, 0.00, 'NO SE RECIBIÓ INFORMACIÓN PARA REPORTAR POR PARTE DEL DEV. SUPUESTAMENTE HAY 1 PRODUCTO PRESENTADO EN EL EVENTO. NO SE IDENTIFICÓ EXPERIENCIA DE ESTA FACULTAD'),
(18, 'Ciencias de la Salud', 0.00, 1.00, 'Participación del docente Arturo Diaz del programa Tecnica Profesional en Procesamiento Calidad nutricional de Alimentos en el 3er Encuentro de prácticas docentes "Innovación Educativa Mediadas por las TIC" el día 14 de noviembre del 2024 con el práctica: Emprendimiento Universitario y Organización de Empresas a través de contenidos digitales en Nutrición y Dietética.'),
(18, 'Química y Farmacia', NULL, 1.00, 'Profesor Juan Camilo Pérez Panza. Laboratorio de Análisis y control de calidad. Plataforma virtual para la simulación de las características espectrales UV visible de moléculas químicas (Simulador UV-Vis espectral chemical). NO IDENTIFICADA POR EL DEV'),
(27, 'Arquitectura', NULL, 2.00, 'Laboratocrio de creatividad codigo 17115 y la asignatura de Historia III codigo 17323 virtualizados en 2023 el curso virtulizado en 2024 fue Métodos de estudio, solo se virtualizó 1'),
(27, 'Bellas Artes', 2.00, NULL, '1. Danza: Prof. Tania Iglesias: Psicología del Desarrollo Humano (se ofreció virtual todo el 2024)\n2. Limúsica: Prof. Vanessa Fontalvo: Trabajo de Grado I (se ofreció virtual el 2024-2) ESTE SI \n3. Limúsica: Prof. Angela Marín: Historia de la Música III (curso diseñado para ofrecerse virtual en el 2025-1) ESTE SI\n4. Arte Dramático: Prof. Juan D. González (en proceso de diseño curso virtual para ofrecer en 2025-1) NO COMENZÓ\n4. ProMúsica: prof. Luis Sanchez: Instrumentación I (Para terminar en Octubre aprx) ESTE NO SIGUIÓ'),
(27, 'Ciencias Básicas', 2.00, 0.00, '2024- 1 \n1. Curso Seminario I (Docente Mario Acero) 2023\n2. Fundamentos de Química (Docente Jiress Florez) 2023\n\n2024-2 \nEn esta periodo no se implemento nuevos cursos virtuales. EL INDICADOR EL 0 NINGUN PROFESOR QUISO VIRTUALIZAR LOS CURSOS ASIGNADOS.'),
(27, 'Ciencias Económicas', NULL, 7.00, 'CURSO CORRESPONDIENTE AL PROGRAMA DE PIC 2 ADICIONALES JUAN CARLOS MIRANDA Y DANNY ORTEGA ALVAREZ'),
(27, 'Ciencias Humanas', 0.00, 10.00, 'Se virtualizaron los iguientes cursos para le programa de Interpretación Lenguaje de señas :Lengua de señas I Nueva - Lengua de señas II Nueva- Inclusión social y diversidad Nueva- Introducción a la lingüística 61387- Lenguaje y pensamiento 61242- Competencias comunicativa I 61386- Competencias comunicativa II 61479 - Sociedad y cultura 63715- Historia social de las ciencias 62915- Ética 60606. Interpretación de Lengua de señas.\n\nEs importante señalar que estos cursos ya están completos y se enviaron al MEN para la evaluación y posible obtención del Registro Calificado.'),
(27, 'Ciencias Jurídicas', 1.00, 1.00, 'Se encuentran en proceso de creacion por parte del Departamento de Educación Virtual:\nDivision y territorio (Ciencia Politica), se estima la oferta de esta asignatura para el semestre 2025-1.\nActualmente se encuentra en la oferta academica la asignatura:\nDerecho informatico e Innovación Tecnologica (Derecho)'),
(27, 'Educación', 5.00, 7.00, 'En 2024-1 se virtualizaron 5 asignaturas: Tecnologías\naplicadas a los procesos\ninclusivos II (2024); Seminario de\ntrabajo de grado (2024); Diseño curricular de lenguas extranjeras (2023); Lectura para el desarrollo del pensamiento crítico (2023); Desafíos Impostergables De Las Ciencias Sociales (2023). Para el 2024-2 se virtualizaron 7 asignturas: Comunicación en Lengua de señas, (SI), Enseñanza en la Educación rural en la Infancia, (SI)Enseñanza de la filosofia en la infancia, Seminario de las Tic aplicadas en las ciencias naturales (SI), Inclusión soial y diversidad (Si), Higiene y seguridad deportiva. (SI)'),
(27, 'Ingeniería', 0.00, 0.00, 'NO SE RECIBIÓ INFORMACIÓN PARA REPORTAR\n\nSe virtualizarán 2 cursos de Ingeniería Industrial, los cuales ya fueron aprobados por el Consejo de Facultad: Fundamentos de programación y Bases de datos I.\nDe manera adicional, se virtualizarán los 2 primeros semestres de Ingeniería de Software NO SE VIRTUALIZÓ NINGÚN CURSO .'),
(27, 'Ciencias de la Salud', 0.00, 0.00, 'Se empezó a implementar para el 2024-1 el curso virtual " politicas alimentarias y nutricionales"ESE CURSO ES DE 2023'),
(27, 'Química y Farmacia', NULL, 2.00, 'Dos cursos: Toxicología forense y Educación para la salud (Karen Brochado y Elin Manrique). Ambos ya grabaron videos y están para ofertar en 2025-1NO SE TERMINARON LOS CURSOS SE INCLUYERON PARA 2025'),
